def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    def count_def(seq):
        c = 0
        for x in seq:
            if x == 'D':
                c += 1
        return c

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = count_def(opp)
    my_def = count_def(me)

    # Work out opponent's current response to our previous action.
    last_my, last_opp = history[-1]
    prev_my, prev_opp = history[-2]

    # Persistent defector detection.
    if n >= 5:
        recent_opp = opp[-5:]
        recent_def = count_def(recent_opp)
        if recent_def >= 5:
            return 'D'
        if recent_def >= 4 and opp_def * 2 >= n:
            return 'D'

    # Long-run hostile opponent.
    if n >= 10 and opp_def * 2 > n:
        if opp_def * 4 > n * 3:
            return 'D'

    # Endgame exploitation: against likely cooperators, squeeze the last rounds.
    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    # If opponent just defected, retaliate, but distinguish one-off from runs.
    if last_opp == 'D':
        # Opponent has defected in the last two rounds together.
        if prev_opp == 'D' and me[-1] == 'D':
            # We are in a punishing phase. Avoid endless mutual D with a
            # forgiving opponent: cooperate occasionally to offer a reset.
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Single recent defection.
        if opp_def * 4 <= n:
            # Mostly cooperative opponent: retaliate once.
            if last_my == 'C':
                return 'D'
            # We already defected once; offer cooperation to recover.
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If we just defected and they still cooperated, they are forgiving.
    if last_my == 'D':
        # Reward forgiveness with cooperation, unless they are known defectors.
        if opp_def * 2 <= n:
            return 'C'
        if opp_def * 4 <= n * 3:
            return 'D' if rng.random() < 0.25 else 'C'
        return 'D'

    # Both cooperated last round.
    # Guard against periodic defectors: defect pattern visible in regular gaps.
    if n >= 6:
        # Count alternations of opponent D/C to detect periodic defection.
        recent = opp[-6:]
        transitions = 0
        for i in range(1, len(recent)):
            if recent[i] != recent[i - 1]:
                transitions += 1
        if transitions >= 3 and opp_def >= 2:
            # Likely cyclical or alternating opponent; defect on predicted D.
            # Simple heuristic: defect when last two were CC after a D run.
            if recent[-2] == 'C' and recent[-3] == 'D':
                return 'D'

    # Mostly cooperative opponent: exploit occasionally but keep cooperation.
    if n >= 10 and opp_def * 6 <= n:
        # Occasional exploitation, increasing odds near the end.
        if rng.random() < 0.10 + (n / 1000.0) * 0.45:
            return 'D'
        return 'C'

    # Moderate opponent: keep cooperating while they cooperate, but defect
    # periodically to test and prevent being exploited.
    if opp_def * 3 <= n:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Opponent has a substantial defection history but just cooperated:
    # be cautious and defect sometimes.
    if rng.random() < 0.5:
        return 'D'
    return 'C'
